// Find the MINIMUM k such that check(k) is true
function binarySearchOnAnswer(lo, hi, check) {
    while (lo < hi) {
        const mid = lo + Math.floor((hi - lo) / 2);
        if (check(mid)) {
            hi = mid;       // mid is feasible: try smaller
        } else {
            lo = mid + 1;   // mid not feasible: must go larger
        }
    }
    return lo; // lo === hi: smallest feasible value
}

// Find the MAXIMUM k such that check(k) is true
function binarySearchOnAnswerMax(lo, hi, check) {
    while (lo < hi) {
        const mid = lo + Math.floor((hi - lo + 1) / 2); // +1 to avoid infinite loop
        if (check(mid)) {
            lo = mid;       // mid is feasible: try larger
        } else {
            hi = mid - 1;   // mid not feasible: must go smaller
        }
    }
    return lo;
}

