function minDays(tasks, workers, targetDays) {
    function check(daysPerTask) {
        // Can all tasks be done in targetDays with daysPerTask per task?
        const totalDays = tasks.reduce((sum, t) => sum + Math.ceil(t / workers), 0);
        return totalDays <= targetDays; // simplified example
    }
    return binarySearchOnAnswer(1, Math.max(...tasks), check);
}

