// KOKO EATING BANANAS (#875)
// O(n log(max(piles))) time, O(1) space
function minEatingSpeed(piles, h) {
    // FEASIBILITY CHECK: can Koko eat all piles in h hours at speed k?
    function check(k) {
        let hours = 0;
        for (const pile of piles) {
            hours += Math.ceil(pile / k); // hours for this pile
        }
        return hours <= h;
    }

    let lo = 1;                    // minimum possible speed
    let hi = Math.max(...piles);   // maximum needed speed

    while (lo < hi) {
        const mid = lo + Math.floor((hi - lo) / 2);
        if (check(mid)) {
            hi = mid;       // mid is feasible: try slower
        } else {
            lo = mid + 1;   // mid too slow: need faster
        }
    }
    return lo; // minimum feasible speed
}

