function shipWithinDays(weights, days) {
    function check(capacity) {
        let currLoad = 0, daysNeeded = 1;
        for (const w of weights) {
            if (currLoad + w > capacity) { daysNeeded++; currLoad = 0; }
            currLoad += w;
        }
        return daysNeeded <= days;
    }
    let lo = Math.max(...weights); // must fit heaviest package
    let hi = weights.reduce((a,b)=>a+b, 0); // send all in one day
    while (lo < hi) {
        const mid = lo + Math.floor((hi-lo)/2);
        if (check(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}
