// MEDIAN OF TWO SORTED ARRAYS (#4)
// O(log(min(m,n))) time, O(1) space
function findMedianSortedArrays(nums1, nums2) {
    // Ensure nums1 is the shorter array
    if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);

    const m = nums1.length, n = nums2.length;
    const half = Math.floor((m + n + 1) / 2); // left half size

    let lo = 0, hi = m;
    while (lo <= hi) {
        const i = lo + Math.floor((hi - lo) / 2); // partition nums1 at i
        const j = half - i;                         // partition nums2 at j

        // Get boundary values (handle edge partitions)
        const maxLeft1  = i === 0 ? -Infinity : nums1[i-1];
        const minRight1 = i === m ?  Infinity : nums1[i];
        const maxLeft2  = j === 0 ? -Infinity : nums2[j-1];
        const minRight2 = j === n ?  Infinity : nums2[j];

        if (maxLeft1 <= minRight2 && maxLeft2 <= minRight1) {
            // VALID PARTITION
            if ((m + n) % 2 === 1) {
                return Math.max(maxLeft1, maxLeft2); // odd: left max is median
            } else {
                return (Math.max(maxLeft1, maxLeft2) +
                        Math.min(minRight1, minRight2)) / 2; // even: average
            }
        } else if (maxLeft1 > minRight2) {
            hi = i - 1; // i too large: move left
        } else {
            lo = i + 1; // i too small: move right
        }
    }
    return 0; // unreachable if inputs are valid
}

