// SPLIT ARRAY LARGEST SUM (#410)
// O(n log(sum)) time, O(1) space
function splitArray(nums, k) {
    // FEASIBILITY CHECK: can we split into <= k parts with each part sum <= maxSum?
    function canSplit(maxSum) {
        let parts = 1, currSum = 0;
        for (const num of nums) {
            if (currSum + num > maxSum) {
                parts++;          // start new part
                currSum = num;    // current element starts new part
                if (parts > k) return false; // exceeded k parts
            } else {
                currSum += num;
            }
        }
        return true; // total parts <= k
    }

    // Binary search on answer space
    let lo = Math.max(...nums);              // each part must fit largest element
    let hi = nums.reduce((a,b) => a+b, 0);  // all in one part

    while (lo < hi) {
        const mid = lo + Math.floor((hi - lo) / 2);
        if (canSplit(mid)) {
            hi = mid;       // mid is feasible: try smaller maximum sum
        } else {
            lo = mid + 1;   // mid too small: need larger maximum sum
        }
    }
    return lo;
}

